import json
import torch

state = torch.load('/app/model.pth', map_location='cpu', weights_only=False)

out = {}
for k, v in state.items():
    out[k] = v.detach().cpu().numpy().tolist()

with open('/app/weights.json', 'w') as f:
    json.dump(out, f)

print("Saved weights.json")
print("Sizes:")
for k, v in out.items():
    if isinstance(v, list):
        if v and isinstance(v[0], list):
            print(f"  {k}: {len(v)} x {len(v[0])}")
        else:
            print(f"  {k}: {len(v)}")

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <algorithm>
#include "cJSON.h"
#include "lodepng.h"

static std::vector<std::vector<double>> load_matrix(cJSON* node) {
    std::vector<std::vector<double>> mat;
    int rows = cJSON_GetArraySize(node);
    mat.reserve(rows);
    for (int i = 0; i < rows; i++) {
        cJSON* row = cJSON_GetArrayItem(node, i);
        int cols = cJSON_GetArraySize(row);
        std::vector<double> r;
        r.reserve(cols);
        for (int j = 0; j < cols; j++) {
            r.push_back(cJSON_GetArrayItem(row, j)->valuedouble);
        }
        mat.push_back(std::move(r));
    }
    return mat;
}

static std::vector<double> load_vector(cJSON* node) {
    std::vector<double> v;
    int n = cJSON_GetArraySize(node);
    v.reserve(n);
    for (int i = 0; i < n; i++) {
        v.push_back(cJSON_GetArrayItem(node, i)->valuedouble);
    }
    return v;
}

static std::vector<double> linear(const std::vector<std::vector<double>>& W,
                                  const std::vector<double>& b,
                                  const std::vector<double>& x) {
    int out_dim = (int)W.size();
    int in_dim = (int)W[0].size();
    std::vector<double> y(out_dim, 0.0);
    for (int i = 0; i < out_dim; i++) {
        double s = b[i];
        const auto& row = W[i];
        for (int j = 0; j < in_dim; j++) {
            s += row[j] * x[j];
        }
        y[i] = s;
    }
    return y;
}

static std::vector<double> relu(const std::vector<double>& v) {
    std::vector<double> r(v.size());
    for (size_t i = 0; i < v.size(); i++) {
        r[i] = v[i] > 0.0 ? v[i] : 0.0;
    }
    return r;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    const char* weights_path = argv[1];
    const char* image_path = argv[2];

    FILE* fp = fopen(weights_path, "rb");
    if (!fp) { fprintf(stderr, "Cannot open weights file\n"); return 1; }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    std::vector<char> buf(sz + 1, 0);
    fread(buf.data(), 1, sz, fp);
    fclose(fp);

    cJSON* root = cJSON_Parse(buf.data());
    if (!root) { fprintf(stderr, "Failed to parse weights JSON\n"); return 1; }

    auto W1 = load_matrix(cJSON_GetObjectItem(root, "input_layer.weight"));
    auto b1 = load_vector(cJSON_GetObjectItem(root, "input_layer.bias"));
    auto W2 = load_matrix(cJSON_GetObjectItem(root, "hidden_layer.weight"));
    auto b2 = load_vector(cJSON_GetObjectItem(root, "hidden_layer.bias"));
    auto W3 = load_matrix(cJSON_GetObjectItem(root, "output_layer.weight"));
    auto b3 = load_vector(cJSON_GetObjectItem(root, "output_layer.bias"));
    cJSON_Delete(root);

    unsigned char* pixels = nullptr;
    unsigned width = 0, height = 0;
    unsigned err = lodepng_decode_file(&pixels, &width, &height, LCT_GREY, 8, image_path);
    if (err) {
        fprintf(stderr, "PNG decode error %u: %s\n", err, lodepng_error_text(err));
        return 1;
    }
    if (width != 28 || height != 28) {
        fprintf(stderr, "Expected 28x28 image, got %ux%u\n", width, height);
        free(pixels);
        return 1;
    }

    std::vector<double> x(784);
    for (int i = 0; i < 784; i++) {
        x[i] = (double)pixels[i] / 255.0;
    }
    free(pixels);

    auto h1 = relu(linear(W1, b1, x));
    auto h2 = relu(linear(W2, b2, h1));
    auto out = linear(W3, b3, h2);

    int best = 0;
    double best_v = out[0];
    for (int i = 1; i < 10; i++) {
        if (out[i] > best_v) { best_v = out[i]; best = i; }
    }

    printf("%d\n", best);
    return 0;
}
